L["Musca Auras Guide"] = "Guía de Musca Auras"
L["Learn everything about Musca Auras on WoW Forever: how an aura works, what changed in combat, what works and what does not, step-by-step recipes and ready-made auras to import."] = "Aprende todo sobre Musca Auras en WoW Forever: cómo funciona un aura, qué ha cambiado en combate, qué funciona y qué no, recetas paso a paso y auras listas para importar."
